import React from 'react';
import { Box, Typography } from '@mui/material';
import ArrowBackIosIcon from '@mui/icons-material/ArrowBackIos';
import ArrowForwardIosIcon from '@mui/icons-material/ArrowForwardIos';
import { useNavigate } from 'react-router-dom';
function VerticalMovieCarousel({ movies = [], size = 'large', orientation = 'portrait', title = '' }) {
    const scrollRef = React.useRef(null);
    const [isDragging, setIsDragging] = React.useState(false);
    const [startX, setStartX] = React.useState(0);
    const [scrollLeft, setScrollLeft] = React.useState(0);
    const [canScrollLeft, setCanScrollLeft] = React.useState(false);
    const [canScrollRight, setCanScrollRight] = React.useState(true);
    const navigate = useNavigate();

    const checkScrollPosition = () => {
        const el = scrollRef.current;
        if (!el) return;
        setCanScrollLeft(el.scrollLeft > 0);
        setCanScrollRight(el.scrollLeft + el.clientWidth < el.scrollWidth - 5);
    };

    React.useEffect(() => {
        checkScrollPosition();
        const el = scrollRef.current;
        if (!el) return;
        el.addEventListener('scroll', checkScrollPosition);
        return () => el.removeEventListener('scroll', checkScrollPosition);
    }, []);

    const scrollLeftHandler = () => {
        if (scrollRef.current) {
            const posterWidth = scrollRef.current.firstChild?.offsetWidth || 300;
            scrollRef.current.scrollBy({ left: -posterWidth * 4, behavior: 'smooth' });
            setTimeout(checkScrollPosition, 300);
        }
    };

    const scrollRightHandler = () => {
        if (scrollRef.current) {
            const posterWidth = scrollRef.current.firstChild?.offsetWidth || 300;
            scrollRef.current.scrollBy({ left: posterWidth * 4, behavior: 'smooth' });
            setTimeout(checkScrollPosition, 300);
        }
    };

    const handleMouseDown = (e) => {
        setIsDragging(true);
        setStartX(e.pageX - (scrollRef.current?.offsetLeft || 0));
        setScrollLeft(scrollRef.current?.scrollLeft || 0);
    };

    const handleMouseMove = (e) => {
        if (!isDragging || !scrollRef.current) return;
        e.preventDefault();
        const x = e.pageX - scrollRef.current.offsetLeft;
        const walk = (x - startX) * 1.5;
        scrollRef.current.scrollLeft = scrollLeft - walk;
    };

    const handleMouseUpOrLeave = () => {
        setIsDragging(false);
    };

    const handleMovieClick = (mediaId) => {
        navigate(`/media/${mediaId}`);
        // Scroll to top immediately
        window.scrollTo(0, 0);
    };

    if (!movies || movies.length === 0) {
        return (
            <Box sx={{ padding: '20px', textAlign: 'center' }}>
                <Typography variant="h6">Không có phim để hiển thị</Typography>
            </Box>
        );
    }

    // Styles
    const styles = {
        movieSlider: {
            margin: 'var(--margin-left-right)',
        },
        sliderContainer: {
            position: 'relative',
            flex: 1,
            minWidth: 0,
            overflow: 'hidden',
        },
        movieList: {
            display: 'flex',
            overflowX: 'auto',
            scrollBehavior: 'smooth',
            scrollbarWidth: 'none',
            '&::-webkit-scrollbar': { display: 'none' },
            gap: '16px',
            paddingTop: '30px',
            position: 'relative',
            maskImage:
                'linear-gradient(to right, rgba(0,0,0,0.8), rgba(0,0,0,1) 10%, rgba(0,0,0,1) 90%, rgba(0,0,0,0.8))',
            WebkitMaskImage:
                'linear-gradient(to right, rgba(0,0,0,0.8), rgba(0,0,0,1) 10%, rgba(0,0,0,1) 90%, rgba(0,0,0,0.8))',
        },
        movieItem: {
            flex: '0 0 auto',
            position: 'relative',
            borderRadius: '8px',
            overflow: 'hidden',
            cursor: 'pointer',
            transition: 'transform 0.3s ease',
            '&:hover': { transform: 'scale(1.05)' },
            width: orientation === 'landscape' ? '300px' : '200px',
            height: orientation === 'landscape' ? '169px' : '300px',
        },
        movieInfo: {
            position: 'absolute',
            bottom: 0,
            left: 0,
            width: '100%',
            background: 'linear-gradient(to top, rgba(0, 0, 0, 0.8), transparent)',
            padding: '10px',
            color: 'white',
            minHeight: '60px',
        },
        navButton: {
            position: 'absolute',
            top: '50%',
            transform: 'translateY(-50%)',
            color: 'white',
            cursor: 'pointer',
            zIndex: 1,
        },
    };

    return (
        <Box sx={styles.movieSlider}>
            {title && (
                <Typography fontWeight={'bold'} variant="body" color="white" fontSize={24}>
                    {title}
                </Typography>
            )}

            <Box sx={styles.sliderContainer}>
                {canScrollLeft && (
                    <Box onClick={scrollLeftHandler} sx={{ ...styles.navButton, left: '10px' }}>
                        <ArrowBackIosIcon sx={{ fontSize: '40px', opacity: 0.7, '&:hover': { opacity: 1 } }} />
                    </Box>
                )}

                <Box
                    ref={scrollRef}
                    sx={styles.movieList}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUpOrLeave}
                    onMouseLeave={handleMouseUpOrLeave}
                >
                    {movies.map((movie, index) => (
                        <Box key={index} sx={styles.movieItem}>
                            <img
                                src={movie.image}
                                alt={movie.title}
                                onDragStart={(e) => e.preventDefault()}
                                style={{
                                    width: '100%',
                                    height: '100%',
                                    objectFit: 'cover',
                                }}
                                onClick={() => handleMovieClick(movie.mediaId)}
                            />
                            <Box sx={styles.movieInfo}>                        
                                {/* Dòng 2: Mô tả */}
                                <Box
                                    sx={{
                                        display: 'flex',
                                        gap: '6px',
                                        alignItems: 'center',
                                        marginTop: '4px',
                                    }}
                                >
                                    {/* Khung cho Release Year */}
                                    <Box
                                        sx={{
                                            background:
                                                'linear-gradient(135deg, rgba(255, 165, 0, 0.7), rgba(255, 140, 0, 0.5))',
                                            border: '1px solid rgba(255, 255, 255, 0.2)',
                                            borderRadius: '6px',
                                            padding: '0px 8px',
                                            backdropFilter: 'blur(8px)',
                                            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3)',
                                        }}
                                    >
                                        <Typography
                                            variant="caption"
                                            sx={{
                                                color: 'white',
                                                fontSize: '11px',
                                                fontWeight: '600',
                                                textShadow: '0 1px 2px rgba(0, 0, 0, 0.5)',
                                            }}
                                        >
                                            {movie.releaseYear}
                                        </Typography>
                                    </Box>

                                    {/* Khung cho Duration */}
                                    <Box
                                        sx={{
                                            background:
                                                'linear-gradient(135deg, rgba(249, 115, 22, 0.8), rgba(245, 158, 11, 0.6))',
                                            border: '1px solid rgba(255, 255, 255, 0.2)',
                                            borderRadius: '6px',
                                            padding: '0px 8px',
                                            backdropFilter: 'blur(8px)',
                                            boxShadow: '0 2px 8px rgba(0, 0, 0, 0.3)',
                                        }}
                                    >
                                        <Typography
                                            variant="caption"
                                            sx={{
                                                color: 'white',
                                                fontSize: '11px',
                                                fontWeight: '600',
                                                textShadow: '0 1px 2px rgba(0, 0, 0, 0.5)',
                                            }}
                                        >
                                            {movie.duration} min
                                        </Typography>
                                    </Box>
                                </Box>
                            </Box>
                        </Box>
                    ))}
                </Box>

                {canScrollRight && (
                    <Box onClick={scrollRightHandler} sx={{ ...styles.navButton, right: '10px' }}>
                        <ArrowForwardIosIcon sx={{ fontSize: '40px', opacity: 0.7, '&:hover': { opacity: 1 } }} />
                    </Box>
                )}
            </Box>
        </Box>
    );
}

export default VerticalMovieCarousel;