'use client';
import { useState, useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { login } from '@/redux/features/auth/authSlice';
import bgImage from '@/assets/images/bg.jpg';
import Notification from '@/components/Notification/Notification';
import useNotification from '@/hooks/useNotification';
import {
    Box,
    Container,
    Paper,
    Typography,
    TextField,
    Button,
    Link,
    InputAdornment,
    IconButton,
    FormControlLabel,
    Checkbox,
    Grid,
    Alert,
} from '@mui/material';
import { Person, Lock, Visibility, VisibilityOff, Style } from '@mui/icons-material';

export default function Login() {
    const [credentials, setCredentials] = useState({ username: '', password: '' });
    const [showPassword, setShowPassword] = useState(false);
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const { loading, error, isAuthenticated } = useSelector((state) => state.auth);
    const { notification, showNotification, closeNotification } = useNotification();

    const togglePasswordVisibility = () => {
        setShowPassword(!showPassword);
    };

    const handleChange = (e) => {
        setCredentials({ ...credentials, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        const result = await dispatch(login(credentials));
        if (login.fulfilled.match(result)) {
            showNotification('Login successful!', 'success');
        }
    };

    // Redirect if already logged in
    useEffect(() => {
        if (isAuthenticated) {
            const redirectPath = sessionStorage.getItem('redirectAfterLogin');
            if (redirectPath) {
                sessionStorage.removeItem('redirectAfterLogin');
                navigate(redirectPath);
            } else {
                navigate('/');
            }
        }
    }, [isAuthenticated, navigate]);

    return (
        <Box
            sx={{
                minHeight: '100vh',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                backgroundImage: `url(${bgImage})`,
                backgroundSize: 'cover',
                backgroundPosition: 'center',
                backgroundRepeat: 'no-repeat',
                position: 'relative',
                '&::before': {
                    content: '""',
                    position: 'absolute',
                    top: 0,
                    left: 0,
                    width: '100%',
                    height: '100%',
                    backgroundColor: 'rgba(0, 0, 0, 0.4)',
                },
            }}
        >
            <Container maxWidth="xs" sx={{ position: 'relative', zIndex: 1 }}>
                <Paper
                    elevation={6}
                    sx={{
                        padding: 4,
                        backgroundColor: 'rgba(18, 18, 18, 0.8)',
                        backdropFilter: 'blur(8px)',
                        color: 'white',
                        borderRadius: 2,
                    }}
                >
                    <Typography variant="h3" align="center" gutterBottom sx={{ fontWeight: 'bold', mb: 3 }}>
                        Login
                    </Typography>

                    <Box component="form" onSubmit={handleSubmit} sx={{ mt: 1 }}>
                        <TextField
                            margin="normal"
                            required
                            fullWidth
                            id="username"
                            label="Username"
                            name="username"
                            autoComplete="username"
                            variant="outlined"
                            value={credentials.username}
                            onChange={handleChange}
                            InputProps={{
                                startAdornment: (
                                    <InputAdornment position="start">
                                        <Person sx={{ color: 'var(--primary)' }} />
                                    </InputAdornment>
                                ),
                            }}
                            sx={{
                                mb: 3,
                                fontSize: '1.2rem',
                                '& .MuiOutlinedInput-root': {
                                    '& fieldset': { borderColor: 'rgba(255, 255, 255, 0.23)' },
                                    '&:hover fieldset': { borderColor: 'rgba(255, 255, 255, 0.5)' },
                                    '&.Mui-focused fieldset': { borderColor: 'var(--primary)' },
                                },
                                '& .MuiInputLabel-root': {
                                    fontSize: '1.2rem',
                                    color: 'rgba(255, 255, 255, 0.7)',
                                    '&.Mui-focused': { color: 'var(--primary)' },
                                },
                                '& .MuiOutlinedInput-input': { color: 'white', fontSize: '1.2rem' },
                            }}
                        />

                        <TextField
                            margin="normal"
                            required
                            fullWidth
                            name="password"
                            label="Password"
                            type={showPassword ? 'text' : 'password'}
                            id="password"
                            autoComplete="current-password"
                            variant="outlined"
                            value={credentials.password}
                            onChange={handleChange}
                            InputProps={{
                                startAdornment: (
                                    <InputAdornment position="start">
                                        <Lock sx={{ color: 'var(--primary)' }} />
                                    </InputAdornment>
                                ),
                                endAdornment: (
                                    <InputAdornment position="end">
                                        <IconButton
                                            aria-label="toggle password visibility"
                                            onClick={togglePasswordVisibility}
                                            edge="end"
                                            sx={{ color: 'var(--primary)' }}
                                        >
                                            {showPassword ? <VisibilityOff /> : <Visibility />}
                                        </IconButton>
                                    </InputAdornment>
                                ),
                            }}
                            sx={{
                                mb: 3,
                                fontSize: '1.2rem',
                                '& .MuiOutlinedInput-root': {
                                    '& fieldset': { borderColor: 'rgba(255, 255, 255, 0.23)' },
                                    '&:hover fieldset': { borderColor: 'rgba(255, 255, 255, 0.5)' },
                                    '&.Mui-focused fieldset': { borderColor: 'var(--primary)' },
                                },
                                '& .MuiInputLabel-root': {
                                    fontSize: '1.2rem',
                                    color: 'rgba(255, 255, 255, 0.7)',
                                    '&.Mui-focused': { color: 'var(--primary)' },
                                },
                                '& .MuiOutlinedInput-input': { color: 'white', fontSize: '1.2rem' },
                            }}
                        />

                        <Grid container sx={{ mb: 3 }}>
                            <Grid item xs>
                                <FormControlLabel
                                    control={
                                        <Checkbox
                                            value="remember"
                                            color="primary"
                                            sx={{
                                                color: 'white',
                                                '&.Mui-checked': {
                                                    color: 'var(--primary)',
                                                },
                                            }}
                                        />
                                    }
                                    label="Remember me"
                                    sx={{ fontSize: '1.1rem', color: 'rgba(255, 255, 255, 0.7)' }}
                                />
                            </Grid>
                            <Grid item>
                                <Link
                                    href="#"
                                    variant="body2"
                                    sx={{
                                        fontSize: '1.1rem',
                                        color: 'var(--primary)',
                                        textDecoration: 'none',
                                        '&:hover': {
                                            textDecoration: 'underline var(--primary)',
                                        },
                                    }}
                                >
                                    Forgot password?
                                </Link>
                            </Grid>
                        </Grid>

                        {error && (
                            <Alert severity="error" sx={{ mb: 2, lineHeight: 2, fontSize: 12 }}>
                                {error}
                            </Alert>
                        )}

                        <Button
                            type="submit"
                            fullWidth
                            variant="contained"
                            disabled={loading}
                            sx={{
                                mt: 2,
                                mb: 3,
                                py: 1.5,
                                fontSize: '1.1rem',
                                fontWeight: 'bold',
                                borderRadius: '8px',
                                background: 'var(--primary)',
                                '&:hover': {
                                    background: 'var(--primary)',
                                },
                            }}
                        >
                            {loading ? 'Logging in...' : 'Login'}
                        </Button>

                        <Box sx={{ textAlign: 'center', mt: 1 }}>
                            <Typography variant="body2" sx={{ fontSize: '1.1rem', color: 'rgba(255, 255, 255, 0.7)' }}>
                                Don't have an account?{' '}
                                <Link
                                    href="/register"
                                    variant="body2"
                                    sx={{
                                        fontSize: '1.1rem',
                                        color: 'var(--primary)',
                                        textDecoration: 'none',
                                        '&:hover': {
                                            textDecoration: 'underline var(--primary)',
                                        },
                                    }}
                                >
                                    Register now
                                </Link>
                            </Typography>
                        </Box>
                    </Box>
                </Paper>
            </Container>
            <Notification notification={notification} closeNotification={closeNotification} />
        </Box>
    );
}
